import React, { useRef } from 'react';

export interface RadioChangeEvent {
  target: {
    checked: boolean;
    value: any;
    name?: string;
  };
  nativeEvent: React.ChangeEvent<HTMLInputElement>['nativeEvent'];
}

export interface RadioProps
  extends Omit<React.ComponentPropsWithoutRef<'input'>, 'onChange'> {
  /** Specifies whether the radio is selected (Controlled) */
  checked?: boolean;
  /** Specifies the initial state (Uncontrolled) */
  defaultChecked?: boolean;
  /** Disable radio button */
  disabled?: boolean;
  /** Value generated by input when used in a group or form */
  value?: any;
  /** Name attribute for underlying input */
  name?: string;
  /** Callback triggered when state changes */
  onChange?: (e: React.ChangeEvent<HTMLInputElement>) => void;
  /** Label content */
  children?: React.ReactNode;
  /** Custom CSS class for the outer <label> container */
  className?: string;
}

export const Radio = React.forwardRef<HTMLInputElement, RadioProps>(
  (
    {
      checked,
      defaultChecked,
      disabled = false,
      value,
      name,
      onChange,
      children,
      className = '',
      style,
      id,
      autoFocus,
      tabIndex,
      ...restProps
    },
    ref
  ) => {
    const internalRef = useRef<HTMLInputElement>(null);
    const inputRef = (ref as React.RefObject<HTMLInputElement>) || internalRef;

    const labelClasses = [
      'custom-radio-wrapper',
      disabled ? 'custom-radio-disabled' : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    return (
      <label className={labelClasses} style={style}>
        <input
          ref={inputRef}
          type="radio"
          id={id}
          name={name}
          value={value}
          checked={checked}
          defaultChecked={defaultChecked}
          disabled={disabled}
          autoFocus={autoFocus}
          tabIndex={tabIndex}
          onChange={onChange}
          className="custom-radio-input"
          {...restProps}
        />
        {children !== undefined && children !== null && (
          <span className="custom-radio-label">{children}</span>
        )}
      </label>
    );
  }
);

